/bin/bash -lc "python - <<'PY'
import json
for fn in ['description-review-input.json','book-model.json','positive-profiles.json','native-national-scope.json','prerequisite-context.json','memory-cards.json']:
 d=json.load(open(fn)); print('\\nFILE',fn)
 if fn=='description-review-input.json':
  print(json.dumps(d['goals'][0],ensure_ascii=False,indent=2));print('GOAL KEYS',list(d['goals'][0]))
 elif fn=='book-model.json':
  for k in ['book','source','navigation','chapters']: print(k, json.dumps(d[k],ensure_ascii=False)[:3500])
  print('PAGES',len(d['pages']),'FIRST PAGE KEYS',list(d['pages'][0]));print(json.dumps(d['pages'][0],ensure_ascii=False,indent=2)[:10000])
 elif fn=='positive-profiles.json': print(json.dumps(d[0],ensure_ascii=False,indent=2))
 elif fn=='native-national-scope.json':
  print({k:v for k,v in d.items() if k"'!='"'goals'});print('GOALS TYPE',type(d['goals']).__name__);print(json.dumps(d['goals'][0],ensure_ascii=False,indent=2))
 elif fn=='prerequisite-context.json': print(json.dumps(d[0],ensure_ascii=False,indent=2))
 else: print(json.dumps(d,ensure_ascii=False,indent=2))
PY"

